pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        vm.prank(c.owner());
        c.mintToken(address(this), 1000);

        vm.prank(c.owner());
        bool ok;
        try c.burn(100) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
